// Lower case, letters / marks / digits only, one space between words, repeated letters squashed
// ("hiiii" -> "hi"): the very same normalisation the server applies.
String normalizeGreetingText(String text) => text
    .toLowerCase()
    .replaceAll(RegExp(r'[^\p{L}\p{M}\p{N}]+', unicode: true), ' ')
    .replaceAllMapped(RegExp(r'(.)\1+', unicode: true), (m) => m.group(1)!)
    .trim()
    .replaceAll(RegExp(r'\s+'), ' ');

final List<List<String>> _kPhraseWords = [
  for (final p in _kGreetingPhrases) p.split(' '),
]..sort((a, b) => b.length.compareTo(a.length));

// True when the whole message is a greeting and nothing else. A message with any real content
// ("hare krishna, what is karma?") is not a greeting.
bool isGreetingMessage(String text) {
  final words = normalizeGreetingText(text).split(' ').where((w) => w.isNotEmpty).toList();
  if (words.isEmpty || words.length > 8) return false;
  var i = 0;
  var matched = 0;
  while (i < words.length) {
    List<String>? hit;
    for (final ph in _kPhraseWords) {
      if (i + ph.length > words.length) continue;
      var ok = true;
      for (var k = 0; k < ph.length; k++) {
        if (words[i + k] != ph[k]) {
          ok = false;
          break;
        }
      }
      if (ok) {
        hit = ph;
        break;
      }
    }
    if (hit != null) {
      matched++;
      i += hit.length;
    } else if (_kGreetingFillers.contains(words[i])) {
      i++;
    } else {
      return false;
    }
  }
  return matched > 0;
}
